class Solution {
 int B; vector<vector<int>> ch; vector<int> buy,sell;
 pair<vector<int>,vector<int>> dfs(int u){
  const int NEG=-1000000000;
  vector<int> no(B+1,NEG),yes(B+1,NEG); no[0]=yes[0]=0;
  vector<pair<vector<int>,vector<int>>> kids;
  for(int v:ch[u]) kids.push_back(dfs(v));
  vector<vector<int>> res(2,vector<int>(B+1,NEG));
  for(int parent=0;parent<2;++parent){
   int cost=parent?buy[u]/2:buy[u];
   for(int take=0;take<2;++take){
    if(take && cost>B)continue;
    vector<int> dp(B+1,NEG);dp[take?cost:0]=take?sell[u]-cost:0;
    for(auto &kid:kids){
     vector<int> nd(B+1,NEG);const vector<int>& options=take?kid.second:kid.first;
     for(int a=0;a<=B;++a)if(dp[a]!=NEG)for(int b=0;a+b<=B;++b)if(options[b]!=NEG)
      nd[a+b]=max(nd[a+b],dp[a]+options[b]);
     dp.swap(nd);
    }
    for(int j=0;j<=B;++j)res[parent][j]=max(res[parent][j],dp[j]);
   }
  }
  return {res[0],res[1]};
 }
public:
 int maxProfit(int n,vector<int>& present,vector<int>& future,vector<vector<int>>& hierarchy,int budget){
  B=budget;buy=present;sell=future;ch.assign(n,{});
  for(auto &e:hierarchy)ch[e[0]-1].push_back(e[1]-1);
  auto p=dfs(0).first;return max(0,*max_element(p.begin(),p.end()));
 }
};
